:root {
  --card-bg: #f2e8d5;
  --card-border: #8b6e4e;
  --header-bg: #3b2e1e;
  --header-text: #f2e8d5;
  --label-text: #c9a96e;
  --number-text: #f2e8d5;
  --swatch-a: #1c3f6e;
  --swatch-b: #a04a2f;
  --swatch-c: #1e1a17;
  --swatch-d: #6b4a28;
  --swatch-e: #9e2040;
  --swatch-caption: #4a3520;
  --formula-row-alt: #e6d9c2;
  --formula-key: #7a5230;
  --formula-val: #2e2318;
  --divider: #b89a74;
  --footer-bg: #dfd0b3;
  --footer-text: #5a3e26;
}

article.ink-card {
  width: 460px;
  background-color: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: 6px;
  overflow: hidden;
  font-size: 13px;
}

.ink-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background-color: var(--header-bg);
  padding: 10px 16px;
}

.ink-label {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 2.5px;
  color: var(--label-text);
  text-transform: uppercase;
}

.ink-number {
  font-size: 13px;
  font-weight: 400;
  color: var(--number-text);
  letter-spacing: 1px;
}

.ink-swatches {
  display: flex;
  gap: 0;
  border-bottom: 1.5px solid var(--divider);
  padding: 14px 16px 10px;
}

.swatch {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  flex: 1;
  margin: 0;
}

.swatch-block {
  width: 44px;
  height: 44px;
  border-radius: 4px;
  border: 1.5px solid var(--card-border);
}

.swatch-a .swatch-block { background-color: var(--swatch-a); }
.swatch-b .swatch-block { background-color: var(--swatch-b); }
.swatch-c .swatch-block { background-color: var(--swatch-c); }
.swatch-d .swatch-block { background-color: var(--swatch-d); }
.swatch-e .swatch-block { background-color: var(--swatch-e); }

.swatch figcaption {
  font-size: 10px;
  line-height: 1.3;
  color: var(--swatch-caption);
  text-align: center;
  font-weight: 600;
}

.ink-formula {
  padding: 8px 0;
}

.formula-row {
  display: flex;
  gap: 10px;
  padding: 6px 16px;
}

.formula-row:nth-child(even) {
  background-color: var(--formula-row-alt);
}

.formula-key {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--formula-key);
  width: 60px;
  flex-shrink: 0;
}

.formula-val {
  font-size: 13px;
  color: var(--formula-val);
}

.ink-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background-color: var(--footer-bg);
  border-top: 1.5px solid var(--divider);
  padding: 8px 16px;
}

.footer-studio {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 1px;
  color: var(--footer-text);
  text-transform: uppercase;
}

.footer-date {
  font-size: 11px;
  color: var(--footer-text);
}
